{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C11"],
      "claim": "In non-human primates, PET-CT showed PBR102, a close analogue sharing the N,N-diethylamide and fused heteroaromatic core, had high initial brain uptake followed by fast clearance, demonstrating meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Alpidem, a close analogue with the same amide-acetic acid linker and heteroaromatic core, easily crossed the BBB in rat autoradiographic studies with brain/plasma ratios of about 2.0-2.5.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "The close analogue [18F]-(R)-TRACK passed the BBB with high brain uptake in nonhuman primates, supporting adequate CNS exposure for this chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "A related N,N-diethylbenzamide radiotracer showed moderate brain uptake (2.46 %ID/g at 10 min) in mice, confirming transferable brain penetration.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues demonstrate BBB permeability and meaningful CNS exposure, and the physicochemical prior is favorable; therefore the query is predicted to have meaningful CNS access.",
  "evidence_gaps": [
    "No direct human Kp,uu or CSF/plasma measurement for the exact query molecule.",
    "Efflux-transporter liability was not directly measured, but multiple in vivo brain uptake studies in the same chemotype support adequate access."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

